dtsPropsFor.Structure:
/** Shown in the header and used as the .schematic file name. */
name: string;
/** [width (x, west→east), height (y, up), length (z, north→south)]. */
size: [number, number, number];
/** Height of the 3D view in px. Default 520. */
viewHeight?: number;
/** Hide the material list. */
hideMaterials?: boolean;
/** Start with the footprint grid and bounding box shown (the Grid checkbox toggles it). Default off. */
showGrid?: boolean;
children?: React.ReactNode;

dtsPropsFor.Block:
/** "registry:name@meta", e.g. "minecraft:stonebrick@0". */
block: string;
/** [x, y, z] inside the Structure size. */
at: [number, number, number];
/** Raw world metadata, overriding the shape direction rules. Rarely needed. */
meta?: number;

dtsPropsFor.Fill:
block: string;
/** One corner, inclusive. */
from: [number, number, number];
/** Opposite corner, inclusive. */
to: [number, number, number];

dtsPropsFor.Air:
/** One corner (or the single block when to is omitted). */
from: [number, number, number];
/** Opposite corner, inclusive. */
to?: [number, number, number];

dtsPropsFor.Hollow:
block: string;
/** One corner, inclusive. */
from: [number, number, number];
/** Opposite corner, inclusive. */
to: [number, number, number];
/** Leave the floor layer out. */
noFloor?: boolean;
/** Leave the ceiling layer out. */
noCeiling?: boolean;

dtsPropsFor.Stairs:
block: string;
at: [number, number, number];
/** End of a straight run (inclusive), all with the same facing. */
to?: [number, number, number];
/** The side the tall back of the step is on — the direction you walk to go up. */
facing: "north" | "south" | "east" | "west";
/** Hang the step from the ceiling (tall part at the bottom). */
upsideDown?: boolean;

dtsPropsFor.Slab:
block: string;
at: [number, number, number];
/** Opposite corner of a box of slabs, inclusive. */
to?: [number, number, number];
/** Upper half of the block space instead of the lower half. */
top?: boolean;

dtsPropsFor.Pillar:
block: string;
at: [number, number, number];
/** End of a straight run, inclusive. */
to?: [number, number, number];
/** Direction the log/pillar runs. Default "y" (upright). */
axis?: "x" | "y" | "z";

dtsPropsFor.Door:
block: string;
/** Position of the lower half;
the upper half goes directly above. */
at: [number, number, number];
/** Direction you face walking in through the door. */
facing: "north" | "south" | "east" | "west";
hingeRight?: boolean;

dtsPropsFor.Torch:
/** Defaults to "minecraft:torch@0". */
block?: string;
at: [number, number, number];
/** Where the supporting block is: "floor" or the wall direction from the torch. Default "floor". */
on?: "floor" | "north" | "south" | "east" | "west";

dtsPropsFor.Strip:
/** Material: a full block, e.g. "ExtraUtilities:greenscreen@0" (white Lapis Caelestis). */
block: string;
at: [number, number, number];
/** End of a run (inclusive); every block space in the box gets the same strip. */
to?: [number, number, number];
/** Which edge of each block space, named by the two faces that meet there. */
edge: "bottom-north" | "bottom-south" | "bottom-west" | "bottom-east" | "top-north" | "top-south" | "top-west" | "top-east" | "north-west" | "north-east" | "south-west" | "south-east";
/** Thickness in eighths: 1 strip (default), 2 post, 4 pillar. */
size?: 1 | 2 | 4;

dtsPropsFor.Corner:
block: string;
at: [number, number, number];
to?: [number, number, number];
/** Which corner of each block space. */
corner: "bottom-north-west" | "bottom-north-east" | "bottom-south-west" | "bottom-south-east" | "top-north-west" | "top-north-east" | "top-south-west" | "top-south-east";
/** Size in eighths: 1 nook (default), 2 corner, 4 notch. */
size?: 1 | 2 | 4;

dtsPropsFor.ArchShape:
/** Which shape, e.g. "roofTile", "roofOuterCorner", "roofRidge", "stairs", "windowFrame", "archD2", "cylinder". */
shape: "roofTile" | "roofOuterCorner" | "roofInnerCorner" | "roofRidge" | "roofSmartRidge" | "roofValley" | "roofSmartValley" | "roofOverhang" | "roofOverhangOuterCorner" | "roofOverhangInnerCorner" | "cylinder" | "cylinderHalf" | "cylinderQuarter" | "cylinderLargeQuarter" | "anticylinderLargeQuarter" | "pillar" | "post" | "pole" | "bevelledOuterCorner" | "bevelledInnerCorner" | "pillarBase" | "doricCapital" | "ionicCapital" | "corinthianCapital" | "doricTriglyph" | "doricTriglyphCorner" | "doricMetope" | "architrave" | "architraveCorner" | "windowFrame" | "windowCorner" | "windowMullion" | "sphereFull" | "sphereHalf" | "sphereQuarter" | "sphereEighth" | "sphereEighthLarge" | "sphereEighthLargeRev" | "roofOverhangGableLH" | "roofOverhangGableRH" | "roofOverhangGableEndLH" | "roofOverhangGableEndRH" | "roofOverhangRidge" | "roofOverhangValley" | "corniceLH" | "corniceRH" | "corniceEndLH" | "corniceEndRH" | "corniceRidge" | "corniceValley" | "corniceBottom" | "archD1" | "archD2" | "archD3A" | "archD3B" | "archD3C" | "archD4A" | "archD4B" | "archD4C" | "banisterPlainBottom" | "banisterPlain" | "banisterPlainTop" | "balustradeFancy" | "balustradeFancyCorner" | "balustradeFancyWithNewel" | "balustradeFancyNewel" | "balustradePlain" | "balustradePlainOuterCorner" | "balustradePlainWithNewel" | "banisterPlainEnd" | "banisterFancyNewelTall" | "balustradePlainInnerCorner" | "balustradePlainEnd" | "banisterFancyBottom" | "banisterFancy" | "banisterFancyTop" | "banisterFancyEnd" | "banisterPlainInnerCorner" | "slab" | "stairs" | "stairsOuterCorner" | "stairsInnerCorner" | "slopeTileA1" | "slopeTileA2" | "slopeTileB1" | "slopeTileB2" | "slopeTileB3" | "slopeTileC1" | "slopeTileC2" | "slopeTileC3" | "slopeTileC4" | "slopeTileA1SE" | "slopeTileA2SE" | "slopeTileB1SE" | "slopeTileB2SE" | "slopeTileB3SE" | "slopeTileC1SE" | "slopeTileC2SE" | "slopeTileC3SE" | "slopeTileC4SE" | "roofTileSE" | "squareSE" | "slabSE" | "angledRoofRidge" | "doubleRoofTile";
/** Material: a normal opaque block, glass or a slab, e.g. "minecraft:planks@1". The sawbench cuts shapes from it. */
block: string;
at: [number, number, number];
/** End of a run (inclusive); every block space in the box gets the same shape. */
to?: [number, number, number];
/**
 * Two-sided shapes: the side the back is on (uphill for roof tiles, slopes,
 * stairs and banisters; the wall for cornices and overhangs). Corner shapes:
 * the corner between facing and the next direction clockwise (north = the
 * north-east corner). Ridges and valleys: either side across the ridge line
 * (a ridge running east-west takes "north" or "south"). Windows: the glass
 * lies across facing. Round and four-way shapes ignore it. Default "north".
 */
facing?: "north" | "south" | "east" | "west";
/** Turn the shape over (hanging eaves, ceiling corners). Not windows. */
upsideDown?: boolean;
/** Window glass: a glass pane, e.g. "minecraft:glass_pane@0" or "minecraft:stained_glass_pane@15". Roofs and some models take cladding: any block. */
secondary?: string;
/** Banisters and balustrade ends: shift sideways, in blocks (the mod uses ±0.375). */
offsetX?: number;
/** Put the shape on the glowing block (Glow brush / sawbench glow page). */
glow?: boolean;
/** Connections cut with the chisel: bits 1 down, 2 up, 4 north, 8 south, 16 west, 32 east. */
disconnected?: number;
/** Raw tile entity orientation, overriding facing / upsideDown. */
side?: number;
turn?: number;
